class ParseError(Exception):
    def __init__(self, filename, lineno, msg, line_content):
        self.filename = filename
        self.lineno = lineno
        self.msg = msg
        self.line_content = line_content
        super().__init__(f"{filename}:{lineno}: {msg}")

def expand_vars(text, vars_dict):
    res = []
    i=0
    n=len(text)
    while i<n:
        c=text[i]
        if c=='$':
            if i+1>=n:
                res.append('$')
                i+=1
                continue
            nxt=text[i+1]
            if nxt=='$':
                res.append('$'); i+=2
            elif nxt==' ':
                res.append(' '); i+=2
            elif nxt==':':
                res.append(':'); i+=2
            elif nxt=='^':
                res.append('\n'); i+=2
            elif nxt=='\n':
                i+=2
            elif nxt=='{':
                end=text.find('}', i+2)
                if end==-1:
                    res.append('$'); res.append('{'); i+=2
                else:
                    var=text[i+2:end]
                    val=vars_dict.get(var, "")
                    res.append(val)
                    i=end+1
            else:
                j=i+1
                while j<n and (text[j].isalnum() or text[j]=='_' or text[j]=='-'):
                    j+=1
                var=text[i+1:j]
                if var=="":
                    raise ValueError(f"bad $-escape (literal $ must be written as $$)")
                val=vars_dict.get(var, "")
                res.append(val)
                i=j
        else:
            res.append(c); i+=1
    return ''.join(res)

def tokenize_build_line_content(s):
    tokens=[]
    cur=[]
    i=0
    n=len(s)
    while i<n:
        c=s[i]
        if c=='$' and i+1<n:
            nxt=s[i+1]
            if nxt==' ':
                cur.append(' ')
                i+=2
                continue
            elif nxt==':':
                cur.append(':')
                i+=2
                continue
            elif nxt=='$':
                cur.append('$')
                i+=2
                continue
            elif nxt=='\n':
                i+=2
                continue
            elif nxt=='^':
                cur.append('\n')
                i+=2
                continue
            else:
                cur.append('$')
                i+=1
                if nxt=='{':
                    cur.append('{')
                    i+=1
                    while i<n and s[i]!='}':
                        cur.append(s[i]); i+=1
                    if i<n and s[i]=='}':
                        cur.append('}'); i+=1
                else:
                    while i<n and (s[i].isalnum() or s[i]=='_' or s[i]=='-'):
                        cur.append(s[i]); i+=1
                continue
        if c==' ' or c=='\t':
            if cur:
                tokens.append(''.join(cur))
                cur=[]
            while i<n and (s[i]==' ' or s[i]=='\t'):
                i+=1
            continue
        else:
            cur.append(c); i+=1
    if cur:
        tokens.append(''.join(cur))
    return tokens

