def find_closest(target, candidates):
    import difflib
    matches=difflib.get_close_matches(target, candidates, n=1, cutoff=0.6)
    if matches:
        return matches[0]
    for c in candidates:
        if target in c or c in target:
            return c
    return None

def parse_file(filename, manifest, parent_vars=None, scope_vars=None):
