            if buffer=="":
                buffer=line
                buf_lineno=lineno
            else:
                # Append lstrip of current line? spec says whitespace at beginning of line after continuation stripped
                buffer += line.lstrip(' \t')
            # Continue to next line, where leading whitespace stripped
            # But we need to also handle that next line's leading whitespace stripped, which will happen at next iteration when we add
            continue
        else:
            if buffer!="":
                # finalize with current line's lstrip
                final = buffer + line.lstrip(' \t') if buffer else line
                processed_lines.append(final)
                processed_nos.append(buf_lineno)
                buffer=""
                buf_lineno=None
            else:
                processed_lines.append(line)
                processed_nos.append(lineno)
