                    eprint(f"ninja: error: {filename}:{lineno}: expected rule name")
                    sys.exit(1)
                rule_name=parts[1]
                if rule_name in manifest.rules or rule_name in BUILTIN_RULES:
                    eprint(f"ninja: error: {filename}:{lineno}: duplicate rule '{rule_name}'")
                    eprint(stripped)
                    pos=stripped.find(rule_name)+len(rule_name)
                    eprint(' '*(pos) + "^ near here" if pos>=0 else "           ^ near here")
                    sys.exit(1)
                rule=Rule(rule_name)
