# --- parsing helpers ---

def expand_vars(text, vars_dict):
    res=[]
    i=0
    n=len(text)
    while i<n:
        c=text[i]
        if c=='$':
            if i+1>=n:
                res.append('$'); i+=1; continue
            nxt=text[i+1]
            if nxt=='$':
                res.append('$'); i+=2
            elif nxt==' ':
                res.append(' '); i+=2
            elif nxt==':':
                res.append(':'); i+=2
            elif nxt=='^':
                res.append('\n'); i+=2
            elif nxt=='\n':
                i+=2
            elif nxt=='{':
                end=text.find('}', i+2)
                if end==-1:
                    res.append('$'); res.append('{'); i+=2
                else:
                    var=text[i+2:end]
                    res.append(vars_dict.get(var,""))
                    i=end+1
            else:
                j=i+1
                while j<n and (text[j].isalnum() or text[j]=='_' or text[j]=='-'):
                    j+=1
                var=text[i+1:j]
                if var=="":
                    raise ValueError("bad $-escape (literal $ must be written as $$)")
                res.append(vars_dict.get(var,""))
                i=j
        else:
            res.append(c); i+=1
    return ''.join(res)

def tokenize_build_line_content(s):
    tokens=[]; cur=[]
    i=0; n=len(s)
    while i<n:
        c=s[i]
        if c=='$' and i+1<n:
            nxt=s[i+1]
            if nxt==' ':
                cur.append(' '); i+=2; continue
            elif nxt==':':
                cur.append(':'); i+=2; continue
            elif nxt=='$':
                cur.append('$'); i+=2; continue
            elif nxt=='\n':
                i+=2; continue
            elif nxt=='^':
                cur.append('\n'); i+=2; continue
            else:
                cur.append('$'); i+=1
                if nxt=='{':
                    cur.append('{'); i+=1
                    while i<n and s[i]!='}':
                        cur.append(s[i]); i+=1
                    if i<n and s[i]=='}':
                        cur.append('}'); i+=1
                else:
                    while i<n and (s[i].isalnum() or s[i]=='_' or s[i]=='-'):
                        cur.append(s[i]); i+=1
                continue
        if c==' ' or c=='\t':
            if cur:
                tokens.append(''.join(cur)); cur=[]
            while i<n and (s[i]==' ' or s[i]=='\t'):
                i+=1
            continue
        else:
            cur.append(c); i+=1
    if cur:
        tokens.append(''.join(cur))
    return tokens

class Rule:
    def __init__(self,name):
        self.name=name; self.vars={}; self.filename=None; self.lineno=None
class Build:
    def __init__(self):
        self.outputs=[]; self.implicit_outputs=[]; self.rule_name=None
        self.inputs=[]; self.implicit_inputs=[]; self.order_only_inputs=[]; self.validations=[]
        self.variables={} # raw build variables not yet expanded? We'll store expanded as per scope? For simplicity store expanded with scope
        self.raw_variables={} # raw before expansion with build context (for those containing $in/$out) - but we store expanded already for most; for pool we store expanded
        self.pool=None; self.filename=None; self.lineno=None
        self.restat=False; self.generator=False; self.depfile_raw=None; self.deps_raw=None
        self.rspfile_raw=None; self.rspfile_content_raw=None
        self.description_raw=None; self.dyndep_raw=None
        self.file_vars_snapshot=None
class Pool:
    def __init__(self,name):
        self.name=name; self.depth=None; self.filename=None; self.lineno=None
class Manifest:
    def __init__(self):
        self.rules={}; self.builds=[]; self.pools={}; self.vars={}; self.defaults=[]; self.builddir=None; self.ninja_required_version=None; self.output_to_build={}

def find_closest(target, candidates):
    m=difflib.get_close_matches(target, candidates, n=1, cutoff=0.6)
    if m:
        return m[0]
    for c in candidates:
        if target in c or c in target:
            return c
    return None

def parse_file(filename, manifest, parent_vars=None, scope_vars=None):
    if parent_vars is None:
        parent_vars={}
    if scope_vars is None:
        scope_vars=manifest.vars
    try:
        with open(filename, 'r', encoding='utf-8', errors='surrogateescape') as f:
            raw_lines=f.readlines()
    except FileNotFoundError:
        eprint(f"ninja: error: loading '{filename}': No such file or directory")
        sys.exit(1)
    except IsADirectoryError:
        eprint(f"ninja: error: loading '{filename}': No such file or directory")
        sys.exit(1)
    # handle line continuation $ \n
    processed_lines=[]; processed_nos=[]
    buffer=""; buf_lineno=None
    for idx_raw, raw in enumerate(raw_lines):
        lineno=idx_raw+1
        line=raw.rstrip('\r\n')
        cnt=0
        for ch in reversed(line):
            if ch=='$':
                cnt+=1
            else:
                break
        is_cont=(cnt%2==1)
        if is_cont:
            line=line[:-1]
            if buffer=="":
                buffer=line
                buf_lineno=lineno
            else:
                buffer += line.lstrip(' \t')
            continue
        else:
            if buffer!="":
                final=buffer + line.lstrip(' \t') if buffer else line
                processed_lines.append(final)
                processed_nos.append(buf_lineno)
                buffer=""; buf_lineno=None
            else:
                processed_lines.append(line)
                processed_nos.append(lineno)
    if buffer!="":
        processed_lines.append(buffer)
        processed_nos.append(buf_lineno)
    lines=processed_lines; line_numbers=processed_nos
    current_rule=None; current_pool=None; current_build=None
    is_top_level=(scope_vars is manifest.vars)
    idx=0
    while idx<len(lines):
        line=lines[idx]; lineno=line_numbers[idx]
        stripped=line.lstrip(' \t')
        indent=len(line)-len(stripped)
        is_indented=indent>0
        if stripped=="" or stripped.startswith('#'):
            idx+=1; continue
        if not is_indented:
            current_rule=None; current_pool=None; current_build=None
            if stripped.startswith('rule '):
                parts=stripped.split(None,2)
                if len(parts)<2:
                    eprint(f"ninja: error: {filename}:{lineno}: expected rule name")
                    sys.exit(1)
                rule_name=parts[1]
                if rule_name in manifest.rules or rule_name in BUILTIN_RULES:
                    eprint(f"ninja: error: {filename}:{lineno}: duplicate rule '{rule_name}'")
                    eprint(stripped)
                    pos=stripped.find(rule_name)+len(rule_name)
                    eprint(' '*(pos) + "^ near here" if pos>=0 else "           ^ near here")
                    sys.exit(1)
                rule=Rule(rule_name); rule.filename=filename; rule.lineno=lineno
                manifest.rules[rule_name]=rule; current_rule=rule
            elif stripped.startswith('pool '):
                parts=stripped.split(None,2)
                if len(parts)<2:
                    eprint(f"ninja: error: {filename}:{lineno}: expected pool name")
                    sys.exit(1)
                pool_name=parts[1]
                if pool_name in manifest.pools or pool_name in BUILTIN_POOLS:
                    eprint(f"ninja: error: {filename}:{lineno}: duplicate pool '{pool_name}'")
                    eprint(stripped)
                    pos=stripped.find(pool_name)
                    eprint(' '*(pos+len(pool_name)) + "^ near here")
                    sys.exit(1)
                pool=Pool(pool_name); pool.filename=filename; pool.lineno=lineno
                manifest.pools[pool_name]=pool; current_pool=pool
            elif stripped.startswith('build '):
                content=stripped[len('build '):]
                tokens=tokenize_build_line_content(content)
                colon_idx=None
                for ti,tok in enumerate(tokens):
                    if tok==":":
                        colon_idx=ti; break
                if colon_idx is None:
                    eprint(f"ninja: error: {filename}:{lineno}: expected ':'")
                    sys.exit(1)
                outputs_tokens=tokens[:colon_idx]
                if colon_idx+1 >= len(tokens):
                    eprint(f"ninja: error: {filename}:{lineno}: expected rule name")
                    sys.exit(1)
                rule_name=tokens[colon_idx+1]
                if rule_name!="phony" and rule_name not in manifest.rules:
                    eprint(f"ninja: error: {filename}:{lineno}: unknown build rule '{rule_name}'")
                    eprint(stripped)
                    pos=stripped.find(rule_name)
                    if pos!=-1:
                        eprint(' '*(pos) + "^ near here")
                    sys.exit(1)
                remainder=tokens[colon_idx+2:]
                explicit_outputs=[]; implicit_outputs=[]; mode="explicit"
                for tok in outputs_tokens:
                    if tok=="|":
                        mode="implicit"
                    else:
                        try:
                            expanded=expand_vars(tok, scope_vars)
                        except ValueError as e:
                            eprint(f"ninja: error: {filename}:{lineno}: {e}")
                            eprint(stripped)
                            pos=stripped.find(tok) if tok in stripped else 0
                            eprint(' '*(pos) + "^ near here")
                            sys.exit(1)
                        if expanded=="":
                            eprint(f"ninja: error: {filename}:{lineno}: empty path")
                            eprint(stripped)
                            sys.exit(1)
                        if mode=="explicit":
                            explicit_outputs.append(expanded)
                        else:
                            implicit_outputs.append(expanded)
                if not explicit_outputs:
                    eprint(f"ninja: error: {filename}:{lineno}: expected output file name")
                    sys.exit(1)
                for out in explicit_outputs+implicit_outputs:
                    if out in manifest.output_to_build:
                        eprint(f"ninja: error: {filename}:{lineno}: multiple rules generate {out}")
                        eprint("")
                        sys.exit(1)
                explicit_inputs=[]; implicit_inputs=[]; order_only_inputs=[]; validations=[]; mode="explicit"
                for tok in remainder:
                    if tok=="|":
                        mode="implicit"
                    elif tok=="||":
                        mode="order_only"
                    elif tok=="|@":
                        mode="validations"
                    else:
                        try:
                            expanded=expand_vars(tok, scope_vars)
                        except ValueError as e:
                            eprint(f"ninja: error: {filename}:{lineno}: {e}")
                            eprint(stripped)
                            sys.exit(1)
                        if expanded=="":
                            eprint(f"ninja: error: {filename}:{lineno}: empty path")
                            sys.exit(1)
                        if mode=="explicit":
                            explicit_inputs.append(expanded)
                        elif mode=="implicit":
                            implicit_inputs.append(expanded)
                        elif mode=="order_only":
                            order_only_inputs.append(expanded)
                        elif mode=="validations":
                            validations.append(expanded)
                build=Build()
                build.outputs=explicit_outputs; build.implicit_outputs=implicit_outputs
                build.rule_name=rule_name
                build.inputs=explicit_inputs; build.implicit_inputs=implicit_inputs
                build.order_only_inputs=order_only_inputs; build.validations=validations
                build.filename=filename; build.lineno=lineno
                build.file_vars_snapshot=dict(scope_vars)
                manifest.builds.append(build)
                for out in explicit_outputs+implicit_outputs:
                    manifest.output_to_build[out]=build
                current_build=build
            elif stripped.startswith('default '):
                content=stripped[len('default '):]
                tokens=tokenize_build_line_content(content)
                for tok in tokens:
                    try:
                        expanded=expand_vars(tok, scope_vars)
                    except ValueError as e:
                        eprint(f"ninja: error: {filename}:{lineno}: {e}")
                        sys.exit(1)
                    if expanded=="":
                        eprint(f"ninja: error: {filename}:{lineno}: empty path")
                        sys.exit(1)
                    manifest.defaults.append(expanded)
            elif stripped.startswith('subninja '):
                content=stripped[len('subninja '):].strip()
                try:
                    expanded=expand_vars(content, scope_vars)
                except ValueError as e:
                    eprint(f"ninja: error: {filename}:{lineno}: {e}")
                    sys.exit(1)
                sub_path=os.path.join(os.path.dirname(filename), expanded)
                new_scope=dict(scope_vars)
                parse_file(sub_path, manifest, parent_vars=scope_vars, scope_vars=new_scope)
            elif stripped.startswith('include '):
                content=stripped[len('include '):].strip()
                try:
                    expanded=expand_vars(content, scope_vars)
                except ValueError as e:
                    eprint(f"ninja: error: {filename}:{lineno}: {e}")
                    sys.exit(1)
                inc_path=os.path.join(os.path.dirname(filename), expanded)
                parse_file(inc_path, manifest, parent_vars=parent_vars, scope_vars=scope_vars)
            else:
                if '=' in stripped:
                    eq_idx=stripped.find('=')
                    var_name=stripped[:eq_idx].strip()
                    var_value=stripped[eq_idx+1:].lstrip()
                    try:
                        expanded_value=expand_vars(var_value, scope_vars)
                    except ValueError as e:
                        eprint(f"ninja: error: {filename}:{lineno}: {e}")
                        eprint(stripped)
                        sys.exit(1)
                    if not re.match(r'^[a-zA-Z0-9_.-]+$', var_name):
                        eprint(f"ninja: error: {filename}:{lineno}: unexpected variable '{var_name}'")
                        sys.exit(1)
                    if var_name=="ninja_required_version":
                        manifest.ninja_required_version=expanded_value
                        try:
                            req_parts=re.split(r'[.\-]', expanded_value)
                            req_major=int(req_parts[0]) if req_parts[0].isdigit() else 0
                            req_minor=int(req_parts[1]) if len(req_parts)>1 and req_parts[1].isdigit() else 0
                            cur_major, cur_minor=1,14
                            if req_major>cur_major or (req_major==cur_major and req_minor>cur_minor):
                                eprint(f"ninja: fatal: ninja version ({VERSION}) incompatible with build file ninja_required_version version ({expanded_value}).")
                                sys.exit(1)
                            if req_major!=cur_major:
                                eprint(f"ninja: warning: ninja version ({VERSION}) incompatible with build file ninja_required_version version ({expanded_value}).")
                        except SystemExit:
                            raise
                        except:
                            pass
                        scope_vars[var_name]=expanded_value
                        if is_top_level:
                            manifest.vars[var_name]=expanded_value
                    elif var_name=="builddir":
                        scope_vars[var_name]=expanded_value
                        if is_top_level:
                            manifest.vars[var_name]=expanded_value
                        manifest.builddir=expanded_value
                    else:
                        scope_vars[var_name]=expanded_value
                        if is_top_level:
                            manifest.vars[var_name]=expanded_value
                else:
                    eprint(f"ninja: error: {filename}:{lineno}: expected '=', got identifier")
                    eprint(stripped)
                    eprint("    ^ near here")
                    sys.exit(1)
            idx+=1; continue
        else:
            if current_rule is not None:
                if '=' not in stripped:
                    eprint(f"ninja: error: {filename}:{lineno}: expected '='")
                    sys.exit(1)
                eq_idx=stripped.find('=')
                key=stripped[:eq_idx].strip()
                value=stripped[eq_idx+1:].lstrip()
                allowed={"command","depfile","deps","msvc_deps_prefix","description","generator","restat","rspfile","rspfile_content","pool"}
                if key not in allowed:
                    eprint(f"ninja: error: {filename}:{lineno}: unexpected variable '{key}'")
                    eprint(line)
                    pos=line.find(key)+len(key)
                    eprint(' '*(pos) + " ^ near here")
                    sys.exit(1)
                if key=="command" and "command" in current_rule.vars:
                    eprint(f"ninja: error: {filename}:{lineno}: duplicate command")
                    sys.exit(1)
                current_rule.vars[key]=value
                idx+=1; continue
            elif current_pool is not None:
                if '=' not in stripped:
                    eprint(f"ninja: error: {filename}:{lineno}: expected '='")
                    sys.exit(1)
                eq_idx=stripped.find('=')
                key=stripped[:eq_idx].strip()
                value=stripped[eq_idx+1:].lstrip()
                if key!="depth":
                    eprint(f"ninja: error: {filename}:{lineno}: unexpected variable '{key}'")
                    sys.exit(1)
                try:
                    expanded=expand_vars(value, scope_vars)
                except ValueError as e:
                    eprint(f"ninja: error: {filename}:{lineno}: {e}")
                    sys.exit(1)
                try:
                    depth=int(expanded)
                except:
                    eprint(f"ninja: error: {filename}:{lineno}: invalid pool depth")
                    sys.exit(1)
                current_pool.depth=depth
                idx+=1; continue
            elif current_build is not None:
                if '=' not in stripped:
                    eprint(f"ninja: error: {filename}:{lineno}: expected '='")
                    sys.exit(1)
                eq_idx=stripped.find('=')
                key=stripped[:eq_idx].strip()
                value=stripped[eq_idx+1:].lstrip()
                # For build variables, we need to keep raw for later expansion with $in/$out etc., but pool/restat etc need immediate?
                # Store raw, but also need to handle pool existence check after expansion with file vars
                # For simplicity, expand with file_vars_snapshot immediately for pool etc., but for generic vars expand with scope
                if key=="pool":
                    try:
                        expanded=expand_vars(value, scope_vars)
                    except ValueError as e:
                        eprint(f"ninja: error: {filename}:{lineno}: {e}")
                        eprint(line)
                        sys.exit(1)
                    if expanded not in manifest.pools and expanded not in BUILTIN_POOLS:
                        eprint(f"ninja: error: {filename}:{lineno}: unknown pool '{expanded}'")
                        sys.exit(1)
                    current_build.pool=expanded
                elif key=="restat":
                    try:
                        expanded=expand_vars(value, scope_vars)
                    except ValueError as e:
                        eprint(f"ninja: error: {filename}:{lineno}: {e}")
                        sys.exit(1)
                    current_build.restat=(expanded=="1" or expanded.lower()=="true")
                elif key=="generator":
                    try:
                        expanded=expand_vars(value, scope_vars)
                    except:
                        expanded=value
                    current_build.generator=(expanded=="1")
                elif key=="dyndep":
                    current_build.dyndep_raw=value
                elif key=="depfile":
                    current_build.depfile_raw=value
                elif key=="deps":
                    current_build.deps_raw=value
                elif key=="rspfile":
                    current_build.rspfile_raw=value
                elif key=="rspfile_content":
                    current_build.rspfile_content_raw=value
                elif key=="description":
                    current_build.description_raw=value
                elif key=="msvc_deps_prefix":
                    current_build.msvc_deps_prefix=value
                else:
                    # generic build variable: expand with scope_vars now (immediate)
                    try:
                        expanded=expand_vars(value, scope_vars)
                    except ValueError as e:
                        eprint(f"ninja: error: {filename}:{lineno}: {e}")
                        eprint(line)
                        sys.exit(1)
                    current_build.variables[key]=expanded
                idx+=1; continue
            else:
                eprint(f"ninja: error: {filename}:{lineno}: unexpected indent")
                sys.exit(1)
    for rname, rule in list(manifest.rules.items()):
        if rule.filename==filename and "command" not in rule.vars:
            eprint(f"ninja: error: {filename}:{rule.lineno}: expected 'command =' line")
            eprint(f"rule {rname}")
            sys.exit(1)
    for pname, pool in list(manifest.pools.items()):
        if pool.filename==filename and pool.depth is None:
            eprint(f"ninja: error: {filename}:{pool.lineno}: expected 'depth =' line")
            sys.exit(1)

# --- log handling ---

def get_log_path(manifest):
    if manifest.builddir:
        return os.path.join(manifest.builddir, ".ninja_log")
    return ".ninja_log"

def get_deps_path(manifest):
    if manifest.builddir:
        return os.path.join(manifest.builddir, ".ninja_deps")
    return ".ninja_deps"

def load_log(manifest):
    path=get_log_path(manifest)
    log={}
    if not os.path.exists(path):
        return log
    try:
        with open(path, 'r') as f:
            lines=f.readlines()
            for line in lines[1:]: # skip header
                line=line.rstrip('\n')
                if not line:
                    continue
                parts=line.split('\t')
                if len(parts)>=5:
                    # format: start end mtime output hash
                    try:
                        mtime=parts[2]
                        output=parts[3]
                        h=parts[4]
                        log[output]= (mtime, h)
                    except:
                        pass
                elif len(parts)>=4:
                    pass
    except:
        pass
    return log

def write_log(manifest, log_dict, command_hashes):
    path=get_log_path(manifest)
    dirn=os.path.dirname(path)
    if dirn and not os.path.exists(dirn):
        try:
            os.makedirs(dirn, exist_ok=True)
        except:
            pass
    # read existing to preserve?
    # We'll overwrite with current entries for all outputs built
    try:
        with open(path, 'w') as f:
            f.write("# ninja log v7\n")
            for out, (mtime, h) in log_dict.items():
                # we need start/end dummy
                f.write(f"0\t0\t{mtime}\t{out}\t{h}\n")
            # also include hashes for newly built?
            for out, h in command_hashes.items():
                if out not in log_dict:
                    # need mtime
                    try:
                        m=int(os.path.getmtime(out)*1e9)
                    except:
                        m=0
                    f.write(f"0\t0\t{m}\t{out}\t{h}\n")
    except:
        pass

def command_hash(cmd):
    # simple md5 16 hex chars
    import hashlib
    return hashlib.md5(cmd.encode()).hexdigest()[:16]

def expand_build_vars(build, manifest):
    # prepare vars for expanding rule command etc.
    # file vars from snapshot or manifest
    file_vars = build.file_vars_snapshot if build.file_vars_snapshot is not None else manifest.vars
    combined=dict(file_vars)
    combined.update(build.variables)
    # special vars
    # $in: explicit inputs shell-quoted?
    # For command, $in should be shell-quoted per spec: shell-quoted if it appears in commands.
    # We'll use shlex.quote for each
    combined['in'] = ' '.join(shlex.quote(p) for p in build.inputs) if build.inputs else ""
    combined['in_newline'] = '\n'.join(build.inputs)
    combined['out'] = ' '.join(shlex.quote(p) for p in build.outputs) if build.outputs else ""
    # For deps etc expansion, also need these
    return combined

def get_expanded_command(build, manifest):
    if build.rule_name=="phony":
        return ""
    rule=manifest.rules.get(build.rule_name)
    if not rule:
        return ""
    combined=expand_build_vars(build, manifest)
    try:
        cmd=expand_vars(rule.vars.get('command',''), combined)
    except ValueError:
        cmd=rule.vars.get('command','')
    # Also need to expand other rule vars that may contain $in/$out? Already done via combined
    return cmd

def get_expanded_description(build, manifest):
    if build.rule_name=="phony":
        return ""
    rule=manifest.rules.get(build.rule_name)
    if not rule or 'description' not in rule.vars:
        # check build description_raw?
        if build.description_raw is not None:
            combined=expand_build_vars(build, manifest)
            try:
                return expand_vars(build.description_raw, combined)
            except:
                return build.description_raw
        return ""
    combined=expand_build_vars(build, manifest)
    try:
        return expand_vars(rule.vars['description'], combined)
    except:
        return rule.vars['description']

def get_expanded_depfile(build, manifest):
    if build.depfile_raw is None:
        # also check rule depfile?
        rule=manifest.rules.get(build.rule_name)
        if rule and 'depfile' in rule.vars:
