        pass
    return deps

def save_deps(manifest, deps_dict):
    path=get_deps_path(manifest)
    dirn=os.path.dirname(path)
    if dirn and not os.path.exists(dirn):
        os.makedirs(dirn, exist_ok=True)
    try:
        with open(path, 'w') as f:
            json.dump(deps_dict, f)
    except:
        pass

def parse_depfile(depfile_path):
    # depfile is makefile style: target: dep1 dep2 ...
    # handle line continuations
    try:
        with open(depfile_path,'r') as f:
            content=f.read()
    except:
        return []
    content=content.replace('\\\n',' ')
    # split on ':'
    if ':' not in content:
        return []
    _, deps_part=content.split(':',1)
    # strip line, split whitespace, handle escapes?
    deps=deps_part.strip().split()
    # deps may include \" etc - simplify
    return deps

