def collect_transitive_builds(manifest, target_outputs):
    # BFS from targets following inputs that are outputs
    visited=set()
    queue=list(target_outputs)
    needed_builds=set()
    while queue:
        out=queue.pop()
        if out in visited:
            continue
        visited.add(out)
        b=manifest.output_to_build.get(out)
        if b:
            needed_builds.add(b)
            # for each input that is output, add to queue
            for inp in b.inputs + b.implicit_inputs + b.order_only_inputs:
                if inp in manifest.output_to_build:
                    queue.append(inp)
                # also include validations? validations are added as top-level later
            # also implicit deps from deps log? We'll add deps deps if present
            # For now, add deps from deps dict if available
            # but that requires deps log loaded
    return needed_builds

def topo_sort(builds, manifest):
    # Kahn
    # Build graph edges: build depends on builds that produce its inputs
    build_list=list(builds)
    # map output to build
    out_to_build=manifest.output_to_build
    # compute dependency map
    deps_map={b:set() for b in build_list}
    for b in build_list:
        for inp in b.inputs + b.implicit_inputs + b.order_only_inputs:
            parent=out_to_build.get(inp)
            if parent and parent in deps_map:
                deps_map[b].add(parent)
        # also order_only already included
        # validations not here
    # topo via DFS
    visited={}
    result=[]
    def visit(n):
        if n in visited:
            if visited[n]==1:
                # cycle - ignore
                return
            return
        visited[n]=1
        for dep in deps_map.get(n,[]):
            visit(dep)
        visited[n]=2
        result.append(n)
    for b in build_list:
        if b not in visited:
            visit(b)
    return result

def check_missing_inputs(manifest, needed_builds):
    # For each build in needed, check inputs existence
    for b in needed_builds:
        for inp in b.inputs + b.implicit_inputs + b.order_only_inputs:
            if inp in manifest.output_to_build:
                continue
            if not os.path.exists(inp):
                # phony check: if input is phony output, it may not exist but phony rule makes it virtual? For phony, missing file should be considered not error if phony has no inputs? Actually phony without inputs is considered always out of date if not exists, but not error.
                # Check if inp is phony output without inputs? Still need to consider?
                # For generic, if file missing and no rule, error
                primary_out = b.outputs[0] if b.outputs else "unknown"
                eprint(f"ninja: error: '{inp}', needed by '{primary_out}', missing and no known rule to make it")
                sys.exit(1)

def resolve_targets(manifest, targets, opts):
    # targets from command line may include ^ suffix
    resolved=[]
    all_outputs=set(manifest.output_to_build.keys())
    # also consider phony outputs as targets
    # For each target string
    for t in targets:
        if t.endswith('^'):
            base=t[:-1]
            # find build where base is in inputs (explicit)
            found=None
            for b in manifest.builds:
                if base in b.inputs:
                    found=b.outputs[0] if b.outputs else None
                    break
                # also check implicit?
                if base in b.implicit_inputs:
                    found=b.outputs[0] if b.outputs else None
                    break
            if found:
                resolved.append(found)
            else:
                # fallback to base without ^? Or error unknown target?
                eprint(f"ninja: error: unknown target '{t}'")
                sys.exit(1)
        else:
            resolved.append(t)
    # if resolved empty, use defaults
    if not resolved:
        if manifest.defaults:
            resolved=list(manifest.defaults)
        else:
            # all outputs not used as inputs
            inputs_set=set()
            for b in manifest.builds:
                inputs_set.update(b.inputs)
                inputs_set.update(b.implicit_inputs)
                inputs_set.update(b.order_only_inputs)
            # also implicit outputs are considered outputs, but they are also not inputs?
            # default target statement must appear after build that declares target
            # For default, choose outputs that are not inputs elsewhere
            for b in manifest.builds:
                for out in b.outputs:
                    if out not in inputs_set:
                        if out not in resolved:
                            resolved.append(out)
            # if still empty? maybe all outputs? If all are inputs? then use all?
            if not resolved:
                for b in manifest.builds:
                    for out in b.outputs:
                        if out not in resolved:
                            resolved.append(out)
    else:
        # check unknown targets
        for t in resolved:
            if t not in manifest.output_to_build and not os.path.exists(t):
                # Check if t is input to some build? But we treat as unknown if not output and not exists?
                # In ninja, target may be a file that exists but not output (e.g., source file). Then building it does nothing? Actually if target is source file that exists, ninja says no work? But if missing, error.
                # For phony, target may be phony without file.
                # Check if t is phony output? phony builds produce outputs that are phony, they may not exist.
                if t in manifest.output_to_build:
                    continue
                # Find if any build has t as output implicit?
                # Already covered.
                # Check existence
                if os.path.exists(t):
                    continue
                # Try to suggest
                candidates=list(manifest.output_to_build.keys())
                for b in manifest.builds:
                    candidates.extend(b.inputs)
                sugg=find_closest(t, candidates)
                if sugg:
                    eprint(f"ninja: error: unknown target '{t}', did you mean '{sugg}'?")
                else:
                    eprint(f"ninja: error: unknown target '{t}'")
                sys.exit(1)
    # Expand validations: for each build in transitive closure of resolved, add its validations as extra targets
    # We'll do iterative
    expanded=set(resolved)
    # Need to collect transitive builds first to know validations
    # Use queue
    to_process=list(resolved)
    seen=set()
    while to_process:
        cur=to_process.pop()
        if cur in seen:
            continue
        seen.add(cur)
        b=manifest.output_to_build.get(cur)
        if b:
            for v in b.validations:
                if v not in expanded:
                    expanded.add(v)
                    to_process.append(v)
            # also need to traverse inputs that are outputs (to find further validations)
            for inp in b.inputs + b.implicit_inputs + b.order_only_inputs:
                if inp in manifest.output_to_build:
                    if inp not in seen:
                        to_process.append(inp)
    return list(expanded)

