        # In earlier test with k=1 and one failure, message was "subcommand failed."
        # With k=0 and two jobs one fails, second succeeded, message was "cannot make progress due to previous errors."
        # We'll use generic
        if opts.get('k',1)==0:
            eprint("ninja: build stopped: cannot make progress due to previous errors.")
        else:
            # if failed==1 and total>1? Use subcommand failed?
            # Use subcommand failed for single
            eprint("ninja: build stopped: subcommand failed.")
        return 1
    return 0

