            for b in manifest.builds:
                if not clean_g and b.generator:
                    continue
                to_clean.extend(b.outputs)
                to_clean.extend(b.implicit_outputs)
    # remove duplicates preserve order
    seen=set(); uniq=[]
    for p in to_clean:
        if p not in seen:
            seen.add(p); uniq.append(p)
    # actually clean files that exist
    cleaned=0
