                        os.remove(p)
                    cleaned+=1
            except:
                pass
    # For our simple, if many files, print Cleaning... N files.
    # Determine count of files that would be cleaned
    # In earlier test, cleaning 1 file printed "Cleaning... 1 files."
    # So we print once
    # Need to handle verbose/dryrun affects output?
    # For non-verbose/dryrun, just print Cleaning... X files.
    # For verbose/dryrun, maybe print each?
    # Observed: "Cleaning... 1 files." even with -v?
    # We'll just print that
    count=0
    for p in uniq:
        # count those that existed before cleaning (or would exist)
        # For dryrun, we count those that exist
        if os.path.exists(p) or dryrun:
            # if dryrun, count original existence
            # For now count cleaned + those that would be cleaned
            count+=1
    # But we already cleaned, so for non-dryrun we counted cleaned before removal? Let's recompute after
    # Simpler: count files that were removed (or would be)
    # For our earlier, after cleaning 1 file, remaining files were counted.
    # We'll just print based on cleaned count or target count?
    # For now print cleaned count
