                    if explain:
                        print(f"ninja explain: command line changed for {out}", file=sys.stdout)
                    return True
            else:
                # no log, but output exists -> need to check? If output exists but not in log, we consider need to build? Actually if not in log, maybe need rebuild?
                # We'll treat as needing rebuild if log empty and output exists but command not logged? We'll rely on mtime check.
                pass
    # check inputs mtime
    # compute latest input mtime (including implicit deps from deps log)
    latest=0
    latest_file=""
    for inp in build.inputs + build.implicit_inputs:
        if os.path.exists(inp):
            m=os.path.getmtime(inp)
            if m>latest:
                latest=m; latest_file=inp
        # also check if inp is output of another build that is dirty? But that will be handled via topo order
        # Check deps for this build if deps present
    # include deps from deps_dict
    for out in build.outputs:
        if out in deps_dict:
            for dep in deps_dict[out]:
                if os.path.exists(dep):
                    m=os.path.getmtime(dep)
                    if m>latest:
                        latest=m; latest_file=dep
                else:
                    # missing header: if dep missing, we treat as not needing rebuild unless dep is generated file that was deleted?
                    # Original ninja treats missing dep as still valid (implicitly adds edge but not error if missing)
                    pass
    if latest>0:
        # find earliest output mtime
        earliest=None
        for out in build.outputs + build.implicit_outputs:
            try:
                m=os.path.getmtime(out)
                if earliest is None or m < earliest:
                    earliest=m
            except:
                pass
        if earliest is not None and latest > earliest:
            if explain:
                print(f"ninja explain: {latest_file} is dirty", file=sys.stdout)
            return True
    # check if any order_only dep is missing and will be built? That's handled elsewhere
    # otherwise not needed
    if explain and not needed:
        # print no work reason? Only when explain and not needed, we don't print?
        pass
    return False

