    # args may be: empty, all, depth, rule <name>
    if not args:
        # list defaults or terminals
        if manifest.defaults:
            targets=manifest.defaults
        else:
            # terminals
            inputs=set()
            for b in manifest.builds:
                inputs.update(b.inputs); inputs.update(b.implicit_inputs); inputs.update(b.order_only_inputs)
            targets=[]
            for b in manifest.builds:
                for out in b.outputs:
                    if out not in inputs:
                        targets.append(out)
        # print each as "target: rule"
        for t in targets:
            b=manifest.output_to_build.get(t)
            if b:
                print(f"{t}: {b.rule_name}", file=sys.stdout)
            else:
                print(f"{t}: unknown", file=sys.stdout)
        return 0
    if args[0]=="all":
        for b in manifest.builds:
            for out in b.outputs:
                print(f"{out}: {b.rule_name}", file=sys.stdout)
        return 0
    if args[0]=="depth":
        # sort by depth
        # compute depth via BFS
        depth={}
        def compute_depth(out, visited):
            if out in depth:
                return depth[out]
            if out in visited:
                return 0
            visited.add(out)
            b=manifest.output_to_build.get(out)
            if not b:
                depth[out]=0
                return 0
            d=0
            for inp in b.inputs + b.implicit_inputs:
                if inp in manifest.output_to_build:
                    d=max(d, compute_depth(inp, visited)+1)
            depth[out]=d
            visited.remove(out)
            return d
        all_outs=[]
        for b in manifest.builds:
            all_outs.extend(b.outputs)
        for out in all_outs:
            compute_depth(out, set())
        sorted_outs=sorted(all_outs, key=lambda x: depth.get(x,0))
        # But earlier we printed only terminals for depth? Let's print all sorted
        # To match earlier observed where depth gave only one, we will print terminals sorted?
        # Let's check: if manifest.defaults, maybe depth prints defaults sorted?
        # We'll print terminals sorted by depth
        if manifest.defaults:
            outs=manifest.defaults
        else:
            inputs=set()
            for b in manifest.builds:
                inputs.update(b.inputs); inputs.update(b.implicit_inputs)
            outs=[out for out in all_outs if out not in inputs]
        outs_sorted=sorted(outs, key=lambda x: depth.get(x,0))
        for out in outs_sorted:
            b=manifest.output_to_build.get(out)
            if b:
                print(f"{out}: {b.rule_name}", file=sys.stdout)
        return 0
    if args[0]=="rule":
        if len(args)<2:
            eprint("ninja: error: expected rule name")
            sys.exit(1)
        rule_name=args[1]
        # list targets that use rule
        outs=[]
        for b in manifest.builds:
            if b.rule_name==rule_name:
                outs.extend(b.outputs)
        for out in sorted(outs):
            print(out, file=sys.stdout)
        return 0
    # otherwise, args are maybe list of targets? But for targets tool, extra args are considered targets to filter?
    # Handle unknown mode
    # If first arg is not known, treat as error "unknown target tool mode 'X', did you mean 'all'?"
    candidates=["all","depth","rule"]
    sugg=find_closest(args[0], candidates)
    if sugg:
        eprint(f"ninja: error: unknown target tool mode '{args[0]}', did you mean '{sugg}'?")
    else:
        eprint(f"ninja: error: unknown target tool mode '{args[0]}'")
    sys.exit(1)

def tool_commands(manifest, args, opts):
    # args: options -s and targets
    show_single=False
    targets=[]
    i=0
    while i<len(args):
        if args[i]=='-s':
            show_single=True; i+=1
        elif args[i].startswith('-'):
            eprint(f"commands: invalid option -- '{args[i][1]}'")
            eprint("usage: ninja -t commands [options] [targets]")
            eprint("")
            eprint("options:")
            eprint("  -s     only print the final command to build [target], not the whole chain")
            sys.exit(1)
        else:
            targets.append(args[i]); i+=1
    if not targets:
        # use defaults or all?
        if manifest.defaults:
            targets=list(manifest.defaults)
        else:
            # all outputs not inputs? Use all
            inputs=set()
            for b in manifest.builds:
                inputs.update(b.inputs)
            for b in manifest.builds:
                for out in b.outputs:
                    if out not in inputs:
                        targets.append(out)
            if not targets:
                for b in manifest.builds:
                    targets.extend(b.outputs)
    # collect builds needed for each target
    needed=set()
    for t in targets:
        # BFS
        queue=[t]
        visited=set()
        while queue:
            cur=queue.pop()
            if cur in visited:
                continue
            visited.add(cur)
            b=manifest.output_to_build.get(cur)
            if b:
                needed.add(b)
                for inp in b.inputs + b.implicit_inputs:
                    if inp in manifest.output_to_build:
                        queue.append(inp)
    # topo sort
    ordered=topo_sort(needed, manifest)
    if show_single:
        # only final command for each target? Actually -s means only final command to build [target], not whole chain
        # So for each target, only print its own command, not dependencies
        for t in targets:
            b=manifest.output_to_build.get(t)
            if b and b.rule_name!="phony":
                cmd=get_expanded_command(b, manifest)
                if cmd:
                    print(cmd, file=sys.stdout)
        return 0
    for b in ordered:
        if b.rule_name=="phony":
            continue
        cmd=get_expanded_command(b, manifest)
        if cmd:
            print(cmd, file=sys.stdout)
    return 0

