    print('node [fontsize=10, shape=box, height=0.25]', file=sys.stdout)
    print('edge [fontsize=10]', file=sys.stdout)
    # assign ids
    id_map={}
    counter=0x1000
    def get_id(name):
        nonlocal counter
        if name not in id_map:
            id_map[name]=f"0x{counter:x}"
            counter+=0x100
        return id_map[name]
    # create nodes for each file and rule
    for b in needed:
