        # edges
        for out in b.outputs:
            oid=get_id(out)
            print(f'"{rule_id}" -> "{oid}"', file=sys.stdout)
        # inputs -> rule
        for inp in b.inputs:
            iid=get_id(inp)
            # ensure node exists for inp (if it's file not output, still need node)
