                get_id(inp)
                # print node
                print(f'"{id_map[inp]}" [label="{inp}"]', file=sys.stdout)
            print(f'"{id_map[inp]}" -> "{rule_id}" [label=" {b.rule_name}"]', file=sys.stdout)
        for inp in b.implicit_inputs:
            iid=get_id(inp)
            if inp not in id_map:
                get_id(inp)
                print(f'"{id_map[inp]}" [label="{inp}"]', file=sys.stdout)
            print(f'"{id_map[inp]}" -> "{rule_id}" [arrowhead=none]', file=sys.stdout)
        for inp in b.order_only_inputs:
