    for path in args:
        b=manifest.output_to_build.get(path)
        if b:
            print(f"{path}:", file=sys.stdout)
            print(f"  input: {b.rule_name}", file=sys.stdout)
            for inp in b.inputs:
                print(f"    {inp}", file=sys.stdout)
            for inp in b.implicit_inputs:
                print(f"    {inp}", file=sys.stdout)
            for inp in b.order_only_inputs:
                print(f"    {inp}", file=sys.stdout)
            print(f"  outputs:", file=sys.stdout)
            # find builds that use path as input
            for other in manifest.builds:
                if path in other.inputs or path in other.implicit_inputs or path in other.order_only_inputs:
                    for out in other.outputs:
                        print(f"    {out}", file=sys.stdout)
                    for out in other.implicit_outputs:
                        print(f"    {out}", file=sys.stdout)
        else:
            # check if path is input to some build
            outputs=[]
            for other in manifest.builds:
                if path in other.inputs or path in other.implicit_inputs or path in other.order_only_inputs:
                    outputs.extend(other.outputs)
                    outputs.extend(other.implicit_outputs)
            if outputs:
                print(f"{path}:", file=sys.stdout)
                print(f"  input: unknown", file=sys.stdout)
                print(f"  outputs:", file=sys.stdout)
                for out in outputs:
                    print(f"    {out}", file=sys.stdout)
            else:
                candidates=list(manifest.output_to_build.keys())
                for other in manifest.builds:
                    candidates.extend(other.inputs)
                sugg=find_closest(path, candidates)
                if sugg:
                    eprint(f"ninja: error: unknown target '{path}', did you mean '{sugg}'?")
                else:
                    eprint(f"ninja: error: unknown target '{path}'")
                sys.exit(1)
    return 0

def tool_compdb(manifest, args, opts):
    # args are rules filter, or empty
    # opts may contain -x
    expand_rsp=False
    # parse args for -x
    filtered_rules=[]
    i=0
    while i<len(args):
        if args[i]=='-x':
            expand_rsp=True; i+=1
        elif args[i]=='-h' or args[i]=='--help':
            eprint("usage: ninja -t compdb [options] [rules]")
            eprint("")
            eprint("options:")
            eprint("  -x     expand @rspfile style response file invocations")
            sys.exit(1)
        elif args[i].startswith('-'):
            eprint(f"compdb: invalid option -- '{args[i][1]}'")
            eprint("usage: ninja -t compdb [options] [rules]")
            sys.exit(1)
        else:
            filtered_rules.append(args[i]); i+=1
    entries=[]
    cwd=os.getcwd()
    for b in manifest.builds:
        if filtered_rules and b.rule_name not in filtered_rules:
            continue
        if b.rule_name=="phony":
            continue
        # need command; if no inputs, skip? Original gave empty for no inputs
        if not b.inputs:
            continue
        cmd=get_expanded_command(b, manifest)
        if expand_rsp and '@' in cmd:
            # try to expand rspfile: find @file
            # Simplistic: replace @xxx with content of file xxx
            # Look for pattern @(\S+)
            import re
            def repl(m):
                rsp=m.group(1)
                # strip quotes?
                rsp=rsp.strip('"\'')
                try:
                    with open(rsp, 'r') as f:
                        return f.read().strip()
                except:
                    return m.group(0)
            cmd=re.sub(r'@(\S+)', repl, cmd)
        for inp in b.inputs:
            # For each input, create entry? For link case, each input got entry; for cc case, each c file got entry but for app like foo.o is object, not source. But they still did per input for cc? Earlier we saw for cc, each c file gave entry, but for link, each .o gave entry. So it's per input.
            # But for touch with multiple inputs a b c, they gave per input as well.
            # So generate per input
            entry={
                "directory": cwd,
                "command": cmd,
                "file": inp,
                "output": b.outputs[0] if b.outputs else ""
            }
            entries.append(entry)
    print(json.dumps(entries, indent=2), file=sys.stdout)
    return 0

